<?php
declare(strict_types=1);requireRole('admin');require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/activity.php';$activePage='vision-camp-requests';$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);$db=database();
if($_SERVER['REQUEST_METHOD']==='POST'){$id=filter_input(INPUT_POST,'camp_id',FILTER_VALIDATE_INT);$decision=(string)($_POST['decision']??'');$reason=trim((string)($_POST['rejection_reason']??''));if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';if(!$id||!in_array($decision,['approve-vendor','approve-release','reject'],true))$errors[]='Invalid decision.';if($decision==='reject'&&$reason==='')$errors[]='A rejection reason is required.';if(!$errors){try{$db->beginTransaction();$stmt=$db->prepare('SELECT vc.stage,(SELECT COUNT(*) FROM vision_camp_beneficiaries cb WHERE cb.camp_id=vc.id) registered FROM vision_camps vc WHERE vc.id=:id FOR UPDATE');$stmt->execute(['id'=>$id]);$camp=$stmt->fetch();$stage=$camp['stage']??null;if($decision==='approve-release'&&(int)($camp['registered']??0)<1)throw new RuntimeException('Goods release requires at least one registered beneficiary.');if($decision==='approve-vendor'&&$stage==='awaiting-vendor-approval'){$next='vendor-approved';$sql='vendor_reviewed_by=:user,vendor_reviewed_at=NOW()';}elseif($decision==='approve-release'&&$stage==='awaiting-goods-release'){$next='distribution-in-progress';$sql='goods_released_by=:user,goods_released_at=NOW()';}elseif($decision==='reject'&&in_array($stage,['awaiting-vendor-approval','awaiting-goods-release'],true)){$next='rejected';$sql='vendor_reviewed_by=:user,vendor_reviewed_at=NOW()';}else throw new RuntimeException('Camp is not awaiting this decision.');$update=$db->prepare("UPDATE vision_camps SET stage=:stage,rejection_reason=:reason,$sql WHERE id=:id");$update->execute(['stage'=>$next,'reason'=>$decision==='reject'?$reason:null,'user'=>$_SESSION['user_id'],'id'=>$id]);$db->commit();logActivity('Vision Camps','Updated vision camp stage','VC-'.str_pad((string)$id,4,'0',STR_PAD_LEFT),$next);$_SESSION['flash_success']='Vision camp decision recorded.';unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=vision-camp-requests');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to review camp.';}}}
try{$rows=$db->query('SELECT vc.*,(SELECT GROUP_CONCAT(CONCAT(cb.full_name,CHAR(32,91),cb.nic,CHAR(93)) ORDER BY cb.full_name SEPARATOR 0x2C20) FROM vision_camp_beneficiaries cb WHERE cb.camp_id=vc.id) beneficiary_list,ds.name division_name,d.name district_name,s.company_name,u.full_name requester_name FROM vision_camps vc JOIN ds_divisions ds ON ds.id=vc.ds_division_id JOIN districts d ON d.id=ds.district_id JOIN suppliers s ON s.id=vc.supplier_id JOIN users u ON u.id=vc.requested_by ORDER BY CASE vc.stage WHEN "awaiting-vendor-approval" THEN 0 WHEN "awaiting-goods-release" THEN 1 ELSE 2 END,vc.id DESC')->fetchAll();}catch(PDOException $e){error_log($e->getMessage());$rows=[];$errors[]='Vision camps are unavailable.';}$counts=array_count_values(array_column($rows,'stage'));
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vision Camps | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body><?php require __DIR__.'/../../includes/admin-sidebar.php';?><div class="admin-shell"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-button" id="menu-button">&#9776;</button><h1>Vision Camp / Direct Procurement</h1></div></header><main class="dashboard-content admin-operation-page"><?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=htmlspecialchars(implode(' ',$errors),ENT_QUOTES,'UTF-8')?></div><?php endif;?><section class="operation-summary-grid"><?php foreach([['awaiting-vendor-approval','Awaiting Vendor Approval'],['awaiting-goods-release','Awaiting Goods Release'],['distribution-in-progress','Distribution in Progress'],['completed','Completed']] as [$key,$label]):?><article class="operation-summary-card"><span>&#128203;</span><p><?=$label?></p><strong><?=(int)($counts[$key]??0)?></strong><small>Live camp count</small></article><?php endforeach;?></section><section class="admin-data-card operation-list-card"><div class="admin-data-header"><h2>All Vision Camp Requests</h2></div><div class="admin-data-table-wrap"><table class="admin-data-table vision-camp-table"><thead><tr><th>ID</th><th>Division</th><th>Vendor</th><th>Requested By</th><th>Camp Date</th><th>Identified</th><th>Attended</th><th>Stage</th><th>Action</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="9" class="admin-empty-row">No Vision Camp requests available.</td></tr><?php else:foreach($rows as $r):?><tr><td>VC-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?></td><td><?=htmlspecialchars($r['district_name'].' / '.$r['division_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['company_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['requester_name'],ENT_QUOTES,'UTF-8')?></td><td><?=$r['proposed_date']?:'—'?></td><td><?=$r['people_identified']??'—'?><?php if($r['beneficiary_list']):?><small><?=htmlspecialchars($r['beneficiary_list'])?></small><?php endif;?></td><td><?=$r['attended_count']??'—'?></td><td><?=ucwords(str_replace('-',' ',$r['stage']))?></td><td><?php if(in_array($r['stage'],['awaiting-vendor-approval','awaiting-goods-release'],true)):?><form method="post" class="goods-decision-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="camp_id" value="<?=(int)$r['id']?>"><input name="rejection_reason" placeholder="Rejection reason"><button name="decision" value="<?=$r['stage']==='awaiting-vendor-approval'?'approve-vendor':'approve-release'?>" class="approve-button">Approve</button><button name="decision" value="reject" class="reject-button">Reject</button></form><?php else:?><?=htmlspecialchars($r['rejection_reason']?:'—',ENT_QUOTES,'UTF-8')?><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
